mapper.sql:
WHERE 1 = 1

    AND (
        u.username LIKE CONCAT('%', #{query.keyword}, '%')
        OR l.operation_type LIKE CONCAT('%', #{query.keyword}, '%')
        OR l.action LIKE CONCAT('%', #{query.keyword}, '%')
        OR l.target LIKE CONCAT('%', #{query.keyword}, '%')
        OR l.reason LIKE CONCAT('%', #{query.keyword}, '%')
        OR CAST(l.target_id AS CHAR) = #{query.keyword}
    )


    AND l.operation_type LIKE '%_STATUS'


    AND l.operation_type = #{query.operation}


    AND l.create_time >= #{query.startDate}


    AND l.create_time < DATE_ADD(#{query.endDate}, INTERVAL 1 DAY)
